  },
  {
   "id": "FAM:SF-APPM-022",
   "status_as_recorded": "inconclusive",
   "finding": "Superstar suppression profiles, including Q5c sequential triggering. Recorded verdict: rank-1 suppressor varies meaningfully across players. Example: Jokic after opponent POST_UP 1.1271 (-0.0675, SE ±0.0500, n=480). Rank-1 deltas mostly within 1-2 SE with no multiple-comparison control; OTHER artifact flagged in the document."
  },
  {
   "id": "FAM:SF-APPA-050",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Superstar sequential suppression: opponent play before the star. Recorded PUTBACK as top suppressor for 6+ stars (e.g., D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345, n=32; C. Holmgren d=-0.222, n=52). No multiplicity correction; n_after 32-95 for several PUTBACK cells against thousands of baseline possessions. Sample: 30 stars, min n_after=30. Validation not recorded."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-CHT-025",
   "what_failed": "Using derived play-type labels (initiation_type) from play-by-play to define play types and read PPP differences by play type.",
