 },
 "prior_work": {
  "already_answered": "partly",
  "cited": ["FAM:SF-CHT-025", "FAM:SF07", "FAM:SF-APPM-022", "FAM:SF-APPA-050"],
  "summary": "No retrieved record tests a teammate DRIVE preceding a PNR on PNR PPP. FAM:SF07 addresses sequential pair premiums generally and reports a positive aftershock (8/8 PTs), which partly overlaps with the question's direction but is not the same contrast. FAM:SF-CHT-025 found the play-type labels unreliable. FAM:SF-APPM-022 and FAM:SF-APPA-050 found per-star sequential results inconclusive or not hypothesis tests."
